<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { newRequest, clone, type RequestDraft } from '../model';
import { data } from '../store';
import { useExecution, savePreset, downloadJson, loadCapabilities, capabilities, type PerfResult } from '../execution';
import Icon from '../components/Icon.vue';
import EnvironmentPicker from '../components/EnvironmentPicker.vue';
import KeyValueEditor from '../components/KeyValueEditor.vue';
import ExecutionStatus from '../components/ExecutionStatus.vue';
import ExecutionHistory from '../components/ExecutionHistory.vue';
import PresetBar from '../components/PresetBar.vue';
import PerformanceChart from '../components/PerformanceChart.vue';
type Config = { name: string; engine: string; request: RequestDraft; users: number; duration: number; rampUp: number; thinkTime: number; expectedStatus: number };
const draft = ref<Config>({ name: 'HTTP 性能实验', engine: 'http', request: newRequest(), users: 1, duration: 10, rampUp: 0, thinkTime: 100, expectedStatus: 200 });
const sourceId = ref(''), presetId = ref('');
const { job, result, busy, error, run, cancel, loadHistory } = useExecution<PerfResult>('perf');
const format = (value: number | null | undefined, unit = '') => value == null ? '—' : value + unit;
const metrics = computed(() => [
  { label: '吞吐量', value: format(result.value?.tps), unit: 'req/s', hint: '完成请求 / 实际采样秒数' },
  { label: 'P95', value: format(result.value?.p95Ms), unit: 'ms', hint: '按最近秩法统计' },
  { label: '平均响应', value: format(result.value?.avgMs), unit: 'ms', hint: '包含失败请求耗时' },
  { label: '错误率', value: format(result.value?.errorRate), unit: '%', hint: '传输失败或状态码不符合预期' },
  { label: '请求样本', value: format(result.value?.total), unit: '次', hint: result.value?.capped ? '已达到 100000 个样本上限' : `${result.value?.failed ?? '—'} 次失败` },
]);
function source() { const request = data.requests.find(r => r.id === sourceId.value); if (request) { draft.value.request = clone(request); draft.value.name = request.name + ' · 性能实验'; } }
function load(payload: Config, id: string) { draft.value = clone(payload); presetId.value = id; sourceId.value = ''; }
function save() { presetId.value = savePreset('perf', draft.value.name, draft.value, presetId.value) || ''; }
function profile(users: number, duration: number, rampUp: number) { Object.assign(draft.value, { users, duration, rampUp }); }
onMounted(loadCapabilities);
</script>
<template><div class="page lab-page">
  <div class="page-heading"><div><div class="eyebrow">REQUEST → LOAD → EVIDENCE</div><h1>性能测试</h1><p>复用接口请求建立负载实验，用实测样本核对吞吐、分位耗时与失败原因。</p></div><div class="page-actions"><EnvironmentPicker compact /><button class="button" @click="save"><Icon name="save" />保存实验</button><button class="button primary" :disabled="busy" @click="run(draft)"><Icon :name="busy ? 'loader' : 'play'" :class="{spin: busy}" />{{ busy ? '正在执行' : '开始实验' }}</button></div></div>
  <PresetBar kind="perf" @load="load"><span class="muted help">配置可复用，请求来自现有接口集合</span></PresetBar>
  <div class="lab-config-grid"><section class="card lab-panel"><div class="lab-section-heading"><span class="section-number">01</span><div><h2>请求与判定</h2><p>选择已有用例，或单独定义本次目标。</p></div></div><div class="two-fields"><label class="field">实验名称<input v-model="draft.name" aria-label="性能实验名称" /></label><label class="field">从接口集合载入<select v-model="sourceId" aria-label="性能测试来源请求" @change="source"><option value="">自定义请求</option><option v-for="item in data.requests" :key="item.id" :value="item.id">{{ item.method }} · {{ item.name }}</option></select></label></div><label class="field">目标地址<input v-model="draft.request.url" class="mono" aria-label="性能目标地址" placeholder="{{baseUrl}}/api/path" /></label><div class="three-fields"><label class="field">方法<select v-model="draft.request.method" aria-label="性能请求方法"><option v-for="method in ['GET','POST','PUT','PATCH','DELETE','HEAD']" :key="method">{{ method }}</option></select></label><label class="field">预期状态码<input v-model.number="draft.expectedStatus" type="number" min="100" max="599" aria-label="性能预期状态码" /></label><label class="field">请求超时 ms<input v-model.number="draft.request.timeoutMs" type="number" min="1" max="60000" aria-label="性能请求超时" /></label></div><details class="advanced-config"><summary>请求头与正文 <span>沿用原用例的参数与鉴权</span></summary><KeyValueEditor v-model="draft.request.headers" label="请求头" /><label class="field">正文格式<select v-model="draft.request.body.mode"><option value="none">无正文</option><option value="json">JSON</option><option value="text">文本</option><option value="form">URL 编码表单</option></select></label><KeyValueEditor v-if="draft.request.body.mode === 'form'" v-model="draft.request.body.fields" label="字段" /><textarea v-else-if="draft.request.body.mode !== 'none'" v-model="draft.request.body.text" class="code-editor" aria-label="性能请求体"></textarea></details><p class="lab-footnote">失败按传输结果和预期状态码判定；本实验不执行接口用例中的正文断言。</p></section>
  <section class="card lab-panel"><div class="lab-section-heading"><span class="section-number">02</span><div><h2>负载模型</h2><p>先验证请求，再逐步增加并发。</p></div></div><div class="workload-presets"><button @click="profile(1, 5, 0)">连通性 <strong>1 VU</strong></button><button @click="profile(5, 15, 3)">稳定性 <strong>5 VU</strong></button><button @click="profile(20, 30, 10)">逐步加压 <strong>20 VU</strong></button></div><div class="two-fields"><label class="field">并发用户<input v-model.number="draft.users" type="number" min="1" max="200" aria-label="并发用户" /></label><label class="field">持续时间 s<input v-model.number="draft.duration" type="number" min="1" max="180" aria-label="性能持续时间" /></label><label class="field">爬坡时间 s<input v-model.number="draft.rampUp" type="number" min="0" max="60" aria-label="性能爬坡时间" /></label><label class="field">思考时间 ms<input v-model.number="draft.thinkTime" type="number" min="0" max="10000" aria-label="性能思考时间" /></label></div><label class="field">执行引擎<select v-model="draft.engine" aria-label="性能执行引擎"><option value="http">Node HTTP · 本机并发请求</option><option value="jmeter" :disabled="!capabilities?.jmeter">Apache JMeter {{ capabilities?.jmeter ? '· 已检测到' : '· 尚未检测到' }}</option></select></label><div class="lab-engine-note"><Icon name="perf" :size="18" /><p>{{ draft.engine === 'jmeter' ? '使用本机 Java 运行 JMeter，生成 JMX 与原始 JTL，可下载复现。' : '使用现有 Node 执行适配发出真实并发请求，完整读取响应，按秒聚合图表。' }}</p></div><p class="lab-footnote">当前支持最多 200 VU / 180 秒。JMeter 可通过 JMETER_HOME 配置，未安装时不会冒充 JMeter 执行。</p></section></div>
  <section class="card lab-panel result-panel"><div class="section-title"><div><h2>观测结果</h2><p v-if="result?.config?.url" class="executed-target">执行目标：{{ result.config.url }}</p><p class="muted help">{{ result?.engine || '等待采样' }} · 每个请求最多计一次失败</p></div><button v-if="job && !busy" class="button small" @click="downloadJson(job, `performance-${job.id}.json`)"><Icon name="upload" :size="14" />导出结果</button></div><ExecutionStatus :job="job" :busy="busy" :error="error" @cancel="cancel" /><div class="metrics-strip"><div v-for="item in metrics" :key="item.label" class="metric-cell"><span>{{ item.label }}</span><strong>{{ item.value }}<small>{{ item.unit }}</small></strong><p>{{ item.hint }}</p></div></div><PerformanceChart v-if="result?.timeline?.length" :points="result.timeline" /><div v-else class="chart-empty"><Icon name="perf" :size="30" /><h3>还没有请求样本</h3><p>开始实验后，这里按秒展示实际 TPS 与 P95 曲线。</p></div><div v-if="result && !busy" class="percentile-summary"><span>P50 <b>{{ format(result.p50Ms, ' ms') }}</b></span><span>P99 <b>{{ format(result.p99Ms, ' ms') }}</b></span><span>最小 <b>{{ format(result.minMs, ' ms') }}</b></span><span>最大 <b>{{ format(result.maxMs, ' ms') }}</b></span><span>实际用时 <b>{{ format(result.durationMs / 1000, ' s') }}</b></span></div><div v-if="job?.artifacts.length" class="artifact-links"><a v-for="file in job.artifacts" :key="file.filename" :href="file.url" download><Icon name="upload" :size="13" />{{ file.label }}</a></div><div v-if="result?.samples?.length" class="sample-table"><details><summary>最近 {{ Math.min(result.samples.length, 20) }} 个请求样本</summary><div class="table-scroll"><table><thead><tr><th>完成时间</th><th>耗时</th><th>HTTP</th><th>结果</th><th>失败原因</th></tr></thead><tbody><tr v-for="(s, index) in result.samples.slice(-20)" :key="index"><td>{{ s.offsetMs }} ms</td><td>{{ s.elapsedMs }} ms</td><td>{{ s.status || '—' }}</td><td :class="s.success ? 'text-good' : 'text-bad'">{{ s.success ? '通过' : '失败' }}</td><td>{{ s.error || '—' }}</td></tr></tbody></table></div></details></div></section>
  <ExecutionHistory kind="perf" @select="loadHistory" />
</div></template>
